Author: Mike Holownych <mike@holownych.com>
Date:   Wed Nov 11 06:57:23 2026 +0000

    fix(worktrunk): a named worktree on nexus/* is not a speculative task worktree (v1.1.4 WP-1318)

    Classify task worktrees by the exact shape the task code creates and by the registry, not by a branch/path prefix.

    Co-Authored-By: Claude Sonnet 5.5 <noreply@anthropic.com>

 cli/src/worktrunk/core.ts        | 14 ++++++++++++--
 cli/src/worktrunk/merge.ts       |  7 +++----
 cli/test/worktrunk_merge.test.ts | 22 ++++++++++++++++++++++
 docs/v1.1.4/FINDINGS.md          |  2 +-
 4 files changed, 38 insertions(+), 7 deletions(-)
0169dc61 fix(worktrunk): a named worktree on nexus/* is not a speculative task worktree (v1.1.4 WP-1318) (25 seconds ago) <Mike Holownych>
cli/src/worktrunk/core.ts        | 14 ++++++++++++--
 cli/test/worktrunk_merge.test.ts | 22 ++++++++++++++++++++++
 2 files changed, 34 insertions(+), 2 deletions(-)

cli/src/worktrunk/core.ts
  @@ -121,10 +121,20 @@ export function findEntry(repo: Repo, token: string, home: string): WorktreeEntr
  +/**
  + * Whether the entry is an automated task worktree, by the shape the task-worktree code itself creates
  + * (`WorktreeManager.createWorktree`: branch `nexus/<taskId>` at exactly `<repo>/.nexus/worktrees/<taskId>`) and never one
  + * Nexus registered as a named worktree. A branch merely named `nexus/...` (a named worktree made with `switch -c
  + * nexus/foo` lives at `.nexus/worktrees/nexus-foo`) is not a task worktree.
  + */
  +export function isTaskWorktree(repo: Repo, entry: { branch?: string | null; path: string }, registry: Registry): boolean {
  +  if (!entry.branch?.startsWith("nexus/") || registry.worktrees.some((item) => item.path === entry.path)) return false;
  +  return entry.path === path.join(repo.repoPath, ".nexus", "worktrees", entry.branch.slice("nexus/".length));
  +}
  +
   function kindOf(repo: Repo, entry: WorktreeEntry, registry: Registry): "main" | "task" | "named" | "external" {
     if (entry.isMain) return "main";
  -  const taskBase = path.join(repo.repoPath, ".nexus", "worktrees") + path.sep;
  -  if (entry.branch?.startsWith("nexus/") && entry.path.startsWith(taskBase)) return "task";
  +  if (isTaskWorktree(repo, entry, registry)) return "task";
     return registry.worktrees.some((item) => item.path === entry.path) ? "named" : "external";
   }

  +12 -2

cli/test/worktrunk_merge.test.ts
  @@ -720,6 +720,28 @@ test("merge rejects speculative task worktrees", () => {
  +test("a named worktree on a nexus/* branch merges like any other; a task worktree still does not", () => {
  +  const f = fixture();
  +  try {
  +    const dir = feature(f, "nexus/foo");
  +    assert.equal(dir, dirOf(f, "nexus-foo"));
  +    commitFile(dir, "foo.txt", "foo\n", "foo work");
  +    const r = wt(f, dir, ["merge", ...W, "--no-remove"]);
  +    assert.equal(r.success, true, r.output);
  +    assert.doesNotMatch(r.output, /speculative/i, r.output);
  +    assert.equal(git(f.repo, "log", "-1", "--format=%s"), "foo work");
  +
  +    const taskDir = dirOf(f, "task-abc");
  +    git(f.repo, "worktree", "add", "-q", "-b", "nexus/task-abc", taskDir);
  +    commitFile(taskDir, "t.txt", "t\n", "task work");
  +    const other = feature(f, "feat/other");
  +    commitFile(other, "o.txt", "o\n", "other work");
  +    const refused = wt(f, other, ["merge", "nexus/task-abc", ...W, "--no-remove"]);
  +    assert.equal(refused.success, false, refused.output);
  +    assert.match(refused.output, /speculative task worktree/i, refused.output);
  +  } finally { f.cleanup(); }
  +});
